              AND COALESCE(wst.emp_work_status_name, '') NOT ILIKE U&'%\0E2B\0E22\0E38\0E14%'
          ) * 8) AS work_hours,
          (((COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%') OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%')) OR ((NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E40\0E17\0E04\0E19\0E34\0E04\0E01\0E32\0E23\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E41\0E1E\0E17\0E22\0E4C\0E41\0E1C\0E19%')) AND (NOT (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25\0E27\0E34\0E0A\0E32\0E0A\0E35\0E1E%' OR (COALESCE(pm.emp_position_main_name, '') ILIKE U&'%\0E1E\0E22\0E32\0E1A\0E32\0E25%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22%' AND COALESCE(pm.emp_position_main_name, '') NOT ILIKE U&'%\0E1E\0E19\0E31\0E01\0E07\0E32\0E19%'))) AND (COALESCE(pm.emp_position_main_name, '') ILIKE ANY (ARRAY[U&'%\0E1C\0E14\0E38\0E07\0E04\0E23\0E23\0E20\0E4C%', U&'%\0E40\0E20\0E2A\0E31\0E0A%', U&'%\0E1C\0E39\0E49\0E0A\0E48\0E27\0E22\0E41\0E1E\0E17\0E22\0E4C%', U&'%\0E2D\0E32\0E0A\0E35\0E27\0E2D\0E19\0E32\0E21\0E31\0E22%', U&'%\0E2A\0E34\0E48\